#include <algorithm>
using namespace std;

class Solution {
public:
    int maximumScore(int a, int b, int c) {
        int arr[3] = {a, b, c};
        sort(arr, arr + 3);
        if (arr[2] >= arr[0] + arr[1]) {
            return arr[0] + arr[1];
        }
        return (arr[0] + arr[1] + arr[2]) / 2;
    }
};

import java.util.Arrays;

class Solution {
    public int maximumScore(int a, int b, int c) {
        int[] arr = {a, b, c};
        Arrays.sort(arr);
        if (arr[2] >= arr[0] + arr[1]) {
            return arr[0] + arr[1];
        }
        return (arr[0] + arr[1] + arr[2]) / 2;
    }
}

/**
 * @param {number} a
 * @param {number} b
 * @param {number} c
 * @return {number}
 */
var maximumScore = function(a, b, c) {
    const arr = [a, b, c].sort((x, y) => x - y);
    if (arr[2] >= arr[0] + arr[1]) {
        return arr[0] + arr[1];
    }
    return Math.floor((arr[0] + arr[1] + arr[2]) / 2);
};
